// Monta uma consulta por cliente × plataforma. Datas: do webhook (se enviadas) ou últimos N dias.
const cfg = $('Config').first().json;
let body = {};
try { body = $('Webhook sincronizar').first().json.body || {}; } catch (e) {}

const fmt = (d) => d.toISOString().slice(0, 10);
const today = new Date();
const range = body.date_range || {};
const until = body.date_until || range.end || range.until || range.to || fmt(today);
const since = body.date_since || range.start || range.since || range.from
  || fmt(new Date(today.getTime() - (Number(cfg.daysBack) || 3) * 86400000));
const onlyClient = body.client_id || null;
const onlyPlatform = body.platform || null;

const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c || !c.id) continue;
  if (onlyClient && c.id !== onlyClient) continue;
  const base = { client_id: c.id, client_name: c.name, campaign_type: c.campaign_type, since, until };

  if (c.ad_account_id && (!onlyPlatform || onlyPlatform === 'meta')) {
    const digits = String(c.ad_account_id).replace(/\D/g, '');
    if (digits) out.push({ json: { ...base, platform: 'meta', account_id: 'act_' + digits } });
  }

  if (c.google_ads_id && (!onlyPlatform || onlyPlatform === 'google')) {
    const acc = String(c.google_ads_id).replace(/\D/g, '');
    if (acc) {
      const fields = 'segments.date, campaign.id, campaign.name, campaign.advertising_channel_type, campaign.status, '
        + 'metrics.impressions, metrics.clicks, metrics.cost_micros, metrics.conversions, metrics.conversions_value';
      const where = `segments.date BETWEEN '${since}' AND '${until}'`;
      out.push({ json: { ...base, platform: 'google', kind: 'ads', account_id: acc,
        gaql: `SELECT ${fields}, ad_group.id, ad_group.name, ad_group_ad.ad.id, ad_group_ad.ad.name FROM ad_group_ad WHERE ${where}` } });
      // Performance Max não tem anúncios por grupo: vem no nível da campanha
      out.push({ json: { ...base, platform: 'google', kind: 'pmax', account_id: acc,
        gaql: `SELECT ${fields} FROM campaign WHERE ${where} AND campaign.advertising_channel_type = 'PERFORMANCE_MAX'` } });
    }
  }
}
return out;

const ctx = $('Preparar consultas').item.json;
const j = $json;
const log = { platform: 'meta', client_id: ctx.client_id, client_name: ctx.client_name,
  account_id: ctx.account_id, date_from: ctx.since, date_to: ctx.until };

if (j.error) {
  const msg = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
  return { json: { ...log, status: 'erro', error: msg.slice(0, 500), rows: [] } };
}

// Resultado depende do tipo de campanha cadastrado no cliente
const type = ctx.campaign_type;
const pick = (arr, names) => {
  for (const n of names) {
    const f = (arr || []).find((a) => a.action_type === n);
    if (f) return Number(f.value) || 0;
  }
  return 0;
};
const MSG = ['onsite_conversion.messaging_conversation_started_7d'];
const BUY = ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase'];

const rows = (j.data || []).map((r) => {
  const actions = r.actions || [];
  const values = r.action_values || [];
  let results = 0, result_type = 'alcance', value = 0;
  if (type === 'Mensagem') { results = pick(actions, MSG); result_type = 'conversas'; }
  else if (type === 'Venda') { results = pick(actions, BUY); value = pick(values, BUY); result_type = 'compras'; }
  else { results = Number(r.reach) || 0; }
  return {
    platform: 'meta', client_id: ctx.client_id, client_name: ctx.client_name,
    account_id: ctx.account_id, report_date: r.date_start,
    campaign_id: r.campaign_id, campaign_name: r.campaign_name, campaign_objective: r.objective || null,
    campaign_status: null,
    adset_id: r.adset_id || '', adset_name: r.adset_name || null,
    ad_id: r.ad_id, ad_name: r.ad_name || null,
    impressions: Number(r.impressions) || 0, reach: Number(r.reach) || 0,
    clicks: Number(r.clicks) || 0, link_clicks: Number(r.inline_link_clicks) || 0,
    spend: Number(r.spend) || 0, frequency: r.frequency ? Number(r.frequency) : null,
    results, result_type, conversion_value: value,
    raw: { actions, action_values: values },
  };
});
return { json: { ...log, status: 'ok', error: null, rows } };

const ctx = $('Preparar consultas').item.json;
const j = $json;
const log = { platform: 'google', client_id: ctx.client_id, client_name: ctx.client_name,
  account_id: ctx.account_id, date_from: ctx.since, date_to: ctx.until };

if (j.error) {
  const msg = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
  return { json: { ...log, status: 'erro', error: msg.slice(0, 500), rows: [] } };
}

const rows = (j.results || []).map((r) => {
  const m = r.metrics || {};
  const camp = r.campaign || {};
  const isPmax = ctx.kind === 'pmax';
  const adId = isPmax ? 'pmax-' + camp.id : String((r.adGroupAd && r.adGroupAd.ad && r.adGroupAd.ad.id) || '');
  return {
    platform: 'google', client_id: ctx.client_id, client_name: ctx.client_name,
    account_id: ctx.account_id, report_date: r.segments.date,
    campaign_id: String(camp.id), campaign_name: camp.name || null,
    campaign_objective: camp.advertisingChannelType || null, campaign_status: camp.status || null,
    adset_id: isPmax ? '' : String((r.adGroup && r.adGroup.id) || ''),
    adset_name: isPmax ? null : ((r.adGroup && r.adGroup.name) || null),
    ad_id: adId,
    ad_name: isPmax ? (camp.name || null) : ((r.adGroupAd && r.adGroupAd.ad && r.adGroupAd.ad.name) || null),
    impressions: Number(m.impressions) || 0, reach: null,
    clicks: Number(m.clicks) || 0, link_clicks: null,
    spend: (Number(m.costMicros) || 0) / 1e6, frequency: null,
    results: Number(m.conversions) || 0, result_type: 'conversoes',
    conversion_value: Number(m.conversionsValue) || 0,
    raw: null,
  };
}).filter((r) => r.ad_id);
return { json: { ...log, status: 'ok', error: null, rows } };

// Junta os resultados por cliente × plataforma e monta as linhas do log
const sent = $('Unir').all();
const saved = $input.all();
const groups = new Map();

sent.forEach((s, i) => {
  const d = s.json;
  const saveError = saved[i] && saved[i].json && saved[i].json.error;
  const key = d.platform + '|' + d.client_id + '|' + d.account_id;
  const g = groups.get(key) || { platform: d.platform, client_id: d.client_id, client_name: d.client_name,
    account_id: d.account_id, date_from: d.date_from, date_to: d.date_to, status: 'ok', rows_count: 0, error: null };
  if (d.status === 'erro') { g.status = 'erro'; g.error = d.error; }
  else if (saveError) { g.status = 'erro'; g.error = 'Erro ao gravar: ' + JSON.stringify(saveError).slice(0, 400); }
  else g.rows_count += (d.rows || []).length;
  groups.set(key, g);
});
return [{ json: { runs: Array.from(groups.values()) } }];
